# WolOS wol-light — generated by `wol theme`; edits are overwritten.
$env:WOLOS_THEME = 'wol-light'
$env:WOLOS_PROMPT_ACCENT = '#6e4ee9'
$env:WOLOS_PROMPT_MUTED = '#565563'
$env:WOLOS_PROMPT_OK = '#007f39'
$env:WOLOS_PROMPT_ERROR = '#bb3f27'
$env:WOLOS_PROMPT_SUGGEST = '#858590'
$env:WOLOS_PROMPT_WARN = '#a35500'
if (Get-Command Set-PSReadLineOption -ErrorAction SilentlyContinue) {
    Set-PSReadLineOption -Colors @{
        Default = "`e[38;2;21;21;32m"
        Command = "`e[38;2;110;78;233m"
        Keyword = "`e[38;2;110;78;233m"
        Parameter = "`e[38;2;86;85;99m"
        String = "`e[38;2;0;127;57m"
        Comment = "`e[38;2;86;85;99m"
        Operator = "`e[38;2;163;85;0m"
        Number = "`e[38;2;163;85;0m"
        Variable = "`e[38;2;21;21;32m"
        Type = "`e[38;2;110;78;233m"
        Error = "`e[38;2;187;63;39m"
        InlinePrediction = "`e[38;2;133;133;144m"
    }
}
